<script setup lang="ts">
import { computed,ref } from 'vue'
import AppPage from '../../components/AppPage.vue'
import Icon from '../../components/Icon.vue'
import TrendChart from '../../components/TrendChart.vue'
import EmptyState from '../../components/EmptyState.vue'
import { useHealthStore } from '../../stores/health'
import { dateKey,shortDate } from '../../domain/dates'
import { metricNames,metricUnits } from '../../domain/types'
import type { Metric } from '../../domain/types'
import { averageWeight,bmi,metricRecords } from '../../domain/nutrition'
import { display,navigate } from '../../utils/ui'
const store=useHealthStore(),metric=ref<Metric>('weight'),days=ref(30),end=dateKey()
const metrics:Metric[]=['weight','waist','bodyFat']
const entries=computed(()=>metricRecords(store.data.bodies,metric.value,end,days.value)),latest=computed(()=>metricRecords(store.data.bodies,metric.value,end,36500).slice(-1)[0])
const mean=computed(()=>averageWeight(store.data.bodies,end))
const change=computed(()=>entries.value.length>=2?entries.value[entries.value.length-1][metric.value]!-entries.value[0][metric.value]!:undefined)
const bmiValue=computed(()=>bmi(metricRecords(store.data.bodies,'weight',end,36500).slice(-1)[0]?.weight,store.data.profile.height))
</script>
<template><AppPage title="身体趋势"><text class="eyebrow">PROGRESS, NOT PERFECTION</text><view class="row-between"><text class="page-title">看见自己的变化</text><view class="body-leaf"><Icon name="leaf" :size="23"/></view></view><text class="page-description">体重会波动，你的努力不会白费。</text><view class="body-metric-tabs"><button role="button" v-for="key in metrics" :key="key" :class="{active:metric===key}" @click="metric=key">{{ metricNames[key] }}</button></view><view class="current-metric"><text class="current-caption">{{ latest?'最近记录 · '+shortDate(latest.date):'还没有'+metricNames[metric]+'记录' }}</text><view class="current-value number">{{ display(latest?.[metric],1) }}<text>{{ metricUnits[metric] }}</text></view><text v-if="metric==='weight'" class="current-sub">近7天记录均重 <text>{{ display(mean,1) }}</text> kg</text><text v-else class="current-sub">{{ metric==='waist'?'尽量在相同位置、相同时段测量':'测量设备和状态不同，结果可能存在差异' }}</text></view><view class="body-chart-card"><view class="chart-ranges"><button role="button" v-for="range in [7,30,90]" :key="range" :class="{active:days===range}" @click="days=range">近{{ range }}天</button></view><TrendChart :entries="entries" :metric="metric" :days="days" :end="end"/><view class="body-stats"><view><text class="body-stat-label">近{{ days }}天变化</text><text class="body-stat-number number">{{ change===undefined?'—':(change>0?'+':'')+change.toFixed(1) }}<text>{{ metricUnits[metric] }}</text></text></view><view v-if="metric==='weight'"><text class="body-stat-label">目标体重</text><text class="body-stat-number number">{{ display(store.data.profile.targetWeight,1) }}<text>kg</text></text></view><view v-else><text class="body-stat-label">期间记录</text><text class="body-stat-number number">{{ entries.length }}<text>次</text></text></view><view><text class="body-stat-label">BMI 辅助参考</text><text class="body-stat-number number">{{ display(bmiValue,1) }}</text></view></view></view><view class="notice mt-16"><Icon name="chart" :size="19"/><text>{{ metric==='weight'?'关注趋势，允许日常波动。七日均重基于实际记录日计算，不补齐缺失数据。':'固定测量条件，比追求单次数字更有价值。这里仅展示你的记录，不做诊断。' }}</text></view><button role="button" class="btn-primary mt-24" @click="navigate('body-entry')"><Icon name="plus" tone="white" :size="18"/>记录身体数据</button><view class="section"><view class="section-heading"><text class="section-title">记录历史</text><text class="section-caption">近{{ days }}天 · {{ entries.length }}次</text></view><view v-if="entries.length" class="entry-list"><view v-for="item in [...entries].reverse()" :key="item.id" class="body-history" @click="navigate('body-entry','id='+item.id)"><text class="history-date">{{ item.date }}</text><text class="history-value number">{{ display(item[metric],1) }}<text>{{ metricUnits[metric] }}</text></text><Icon name="edit" tone="muted" :size="16"/></view></view><EmptyState v-else title="先记下此刻的自己" detail="不需要每天测量，选择舒服的记录节奏。" icon="scale" :compact="true"/></view><text class="footer-note">BMI 无法区分肌肉与脂肪，健身人群请结合其他指标观察。</text></AppPage></template>
<style scoped>.body-leaf{width:44px;height:44px;background:#e6eddb;border-radius:50%;display:flex;align-items:center;justify-content:center}.body-metric-tabs{display:flex;gap:10px;margin-top:25px}.body-metric-tabs button{flex:1;border:1px solid var(--line);border-radius:20px;padding:10px;background:var(--white);font-size:12px}.body-metric-tabs button.active{background:var(--green);color:white;border-color:var(--green)}.current-metric{text-align:center;padding:28px 0 20px}.current-caption{font-size:10px;color:var(--muted)}.current-value{font-size:57px;font-weight:600;letter-spacing:-2px;margin:9px 0 8px;line-height:1.1}.current-value text{font-size:15px;letter-spacing:0;font-weight:400;margin-left:8px}.current-sub{font-size:11px;color:var(--muted)}.current-sub text{color:var(--orange);font-weight:600}.body-chart-card{border:1px solid var(--line);border-radius:20px;background:#fafbf5;padding:17px 14px}.chart-ranges{display:flex;gap:4px;justify-content:center;margin-bottom:18px}.chart-ranges button{padding:6px 14px;font-size:10px;color:var(--muted);border-radius:7px}.chart-ranges .active{background:#e6ecdd;color:var(--green);font-weight:550}.body-stats{display:grid;grid-template-columns:repeat(3,1fr);text-align:center;border-top:1px solid var(--line);padding-top:20px;margin-top:16px;padding-bottom:3px}.body-stats>view{border-right:1px solid var(--line)}.body-stats>view:last-child{border:0}.body-stat-label{font-size:9px;color:var(--muted);display:block;margin-bottom:8px}.body-stat-number{font-size:21px;font-weight:550;color:var(--green)}.body-stat-number text{font-size:9px;margin-left:3px;font-weight:400}.body-history{display:flex;align-items:center;gap:17px;border-bottom:1px solid var(--line);padding:15px 4px}.history-date{font-size:12px;color:#77866d;flex:1}.history-value{font-size:18px;font-weight:500}.history-value text{font-size:10px;font-weight:400;color:var(--muted);margin-left:5px}</style>
